type Project = { id:string; name:string; description:string; status:"Planning"|"Active"|"On Hold"|"Completed"|"Archived"; color:string; start_date?:string|null; due_date?:string|null; tasks?:{id:string;status:Status}[]; project_members?:{profile_id:string;role:string}[];category?:string;progress?:number;taskSummary?:string;date?:string };
