function Avatar({initials,color,size="sm"}:{initials:string;color:string;size?:"sm"|"lg"}){return <span className={`avatar ${size}`} style={{background:color}}>{initials}</span>}
function Progress({value,color}:{value:number;color:string}){return <div className="progress"><span style={{width:`${value}%`,background:color}}/></div>}
function DraggableTask({task,onEdit}:{task:Task;onEdit:(task:Task)=>void}){const {attributes,listeners,setNodeRef,transform,isDragging}=useDraggable({id:task.dbId??String(task.id)});return <button ref={setNodeRef} {...listeners} {...attributes} onClick={()=>onEdit(task)} className={`task-card ${isDragging?"dragging":""}`} style={transform?{transform:`translate3d(${transform.x}px,${transform.y}px,0)`}:undefined}><div className="task-card-top"><span className={`priority ${task.priority.toLowerCase()}`}><i/>{task.priority}</span><MoreHorizontal size={16}/></div><strong>{task.title}</strong><small className="task-project"><span style={{background:task.color}}/>{task.project}</small><div className="task-card-bottom"><span className={task.due==="Overdue"?"due overdue":"due"}><CalendarDays size={13}/>{task.due}</span><span className="task-comments"><MessageCircle size={13}/>{task.comments}</span><Avatar initials={task.assignee} color={task.assigneeColor??"#ddd"}/></div></button>}
function KanbanColumn({status,tasks,onEdit,defaultProject}:{status:Status;tasks:Task[];onEdit:(task:Task)=>void;defaultProject:Project|undefined}){const {setNodeRef,isOver}=useDroppable({id:status});return <div className={`kanban-column ${isOver?"over":""}`} ref={setNodeRef}><div className="column-head"><span className={`status-dot ${status.toLowerCase().replaceAll(" ","-")}`}/><b>{status}</b><span className="column-count">{tasks.length}</span><button className="icon-button tiny" aria-label={`Add a task in ${status}`} onClick={()=>onEdit({id:0,title:"",project:defaultProject?.name??"",projectId:defaultProject?.id,status,priority:"Medium",due:"No date",dueDate:null,assignee:"-",assigneeId:null,color:defaultProject?.color??"#7968e8",comments:0})}><Plus size={15}/></button><MoreHorizontal size={16} aria-hidden="true"/></div><div className="column-cards">{tasks.map(task=><DraggableTask key={task.id} task={task} onEdit={onEdit}/>)}{tasks.length===0&&<div className="drop-hint">Drop a task here</div>}</div><button className="add-task" onClick={()=>onEdit({id:0,title:"",project:defaultProject?.name??"",projectId:defaultProject?.id,status,priority:"Medium",due:"",dueDate:null,assignee:"-",assigneeId:null,color:defaultProject?.color??"#7968e8",comments:0})}><Plus size={15}/> Add task</button></div>}

async function safeFetch(input:string,init?:RequestInit):Promise<Response>{try{return await fetch(input,init)}catch{return new Response(JSON.stringify({error:"Could not reach the server. Check your connection and try again."}),{status:503,headers:{"Content-Type":"application/json"}})}}
async function fetchJson(path:string):Promise<unknown>{try{const response=await safeFetch(path);const result=await response.json();return response.ok?result:{error:result.error??`Request failed (${response.status})`}}catch{return{error:"Could not reach the server. Check your connection and try again."}}}

